package main

import (
	"fmt"
	"os/exec"
	"regexp"
	"runtime"
	"strconv"
)

var (
	// Regex for Linux/macOS ping summary: rtt/round-trip min/avg/max/mdev/stddev = x/x/x/x ms
	unixPingRegex = regexp.MustCompile(`(?:rtt|round-trip)\s+min/avg/max/(?:mdev|stddev)\s*=\s*[\d.]+/([\d.]+)/[\d.]+/[\d.]+\s*ms`)
	// Regex for Windows ping summary: Average = Xms
	winPingRegex = regexp.MustCompile(`Average\s*=\s*([\d.]+)\s*ms`)
)

// MeasureLatency pings the specified host a given number of times and returns
// the average latency in milliseconds. It uses os/exec to run the system ping command.
func MeasureLatency(host string, count int) (float64, error) {
	if host == "" {
		return 0, fmt.Errorf("host cannot be empty")
	}
	if count <= 0 {
		return 0, fmt.Errorf("count must be greater than 0")
	}

	var cmd *exec.Cmd
	var parser *regexp.Regexp

	// Adjust command flags and output parser based on the operating system
	switch runtime.GOOS {
	case "windows":
		cmd = exec.Command("ping", "-n", strconv.Itoa(count), host)
		parser = winPingRegex
	case "darwin", "linux":
		cmd = exec.Command("ping", "-c", strconv.Itoa(count), host)
		parser = unixPingRegex
	default:
		return 0, fmt.Errorf("unsupported operating system: %s", runtime.GOOS)
	}

	out, err := cmd.Output()
	// ping often returns a non-zero exit code if there is packet loss,
	// but we can still parse the summary if output was captured.
	if err != nil && len(out) == 0 {
		return 0, fmt.Errorf("failed to execute ping command: %w", err)
	}

	matches := parser.FindStringSubmatch(string(out))
	if len(matches) < 2 {
		return 0, fmt.Errorf("failed to parse average latency from ping output")
	}

	avg, err := strconv.ParseFloat(matches[1], 64)
	if err != nil {
		return 0, fmt.Errorf("failed to convert latency value to float: %w", err)
	}

	return avg, nil
}

func main() {
	host := "8.8.8.8"
	count := 4

	avg, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error measuring latency: %v\n", err)
		return
	}

	fmt.Printf("Average latency to %s over %d pings: %.2f ms\n", host, count, avg)
}

