package main

import (
	"fmt"
	"os/exec"
	"regexp"
	"runtime"
	"strconv"
	"strings"
)

// MeasureLatency pings the specified host a given number of times and returns the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	if host == "" {
		return 0, fmt.Errorf("host cannot be empty")
	}
	if count <= 0 {
		return 0, fmt.Errorf("count must be greater than 0")
	}

	var args []string
	var avgRegex *regexp.Regexp

	// Adjust ping command arguments and output parsing regex based on the host OS
	switch runtime.GOOS {
	case "windows":
		args = []string{"-n", strconv.Itoa(count), host}
		// Windows ping summary example: "Average = 30ms"
		avgRegex = regexp.MustCompile(`(?i)Average\s*=\s*([0-9.,]+)\s*ms`)
	default: // linux, darwin, freebsd, etc.
		args = []string{"-c", strconv.Itoa(count), host}
		// Linux/macOS ping summary example: "rtt min/avg/max/mdev = 0.025/0.030/0.035/0.003 ms"
		avgRegex = regexp.MustCompile(`(?:rtt|round-trip)\s+min/avg/max/[a-z]+\s*=\s*[0-9.,]+/([0-9.,]+)/[0-9.,]+/[0-9.,]+\s*ms`)
	}

	cmd := exec.Command("ping", args...)
	out, err := cmd.CombinedOutput()
	if err != nil {
		return 0, fmt.Errorf("ping command failed: %w, output: %s", err, strings.TrimSpace(string(out)))
	}

	matches := avgRegex.FindStringSubmatch(string(out))
	if len(matches) < 2 {
		return 0, fmt.Errorf("failed to parse average latency from ping output")
	}

	// Handle locales that use commas as decimal separators
	avgStr := strings.ReplaceAll(strings.TrimSpace(matches[1]), ",", ".")
	avg, err := strconv.ParseFloat(avgStr, 64)
	if err != nil {
		return 0, fmt.Errorf("failed to parse latency value %q: %w", avgStr, err)
	}

	return avg, nil
}

func main() {
	host := "8.8.8.8"
	count := 4

	fmt.Printf("Pinging %s %d times...\n", host, count)
	avgLatency, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error measuring latency: %v\n", err)
		return
	}

	fmt.Printf("Average latency: %.2f ms\n", avgLatency)
}

