package main

import (
	"errors"
	"fmt"
	"os"
	"os/exec"
	"regexp"
	"strconv"
)

// MeasureLatency pings the specified host the given number of times and returns the average latency in milliseconds.
// It uses the system 'ping' command via os/exec and parses the output to extract the average RTT.
func MeasureLatency(host string, count int) (float64, error) {
	if host == "" {
		return 0, errors.New("host cannot be empty")
	}
	if count <= 0 {
		return 0, errors.New("count must be positive")
	}

	// Execute ping directly instead of spawning a shell. This is safer and more idiomatic.
	cmd := exec.Command("ping", "-c", strconv.Itoa(count), host)
	// Force C locale to ensure consistent, parseable output across different system languages.
	cmd.Env = append(os.Environ(), "LC_ALL=C")

	output, err := cmd.CombinedOutput()
	if err != nil {
		// ping returns a non-zero exit code on packet loss or unreachable hosts.
		// We only fail immediately if there's no output to parse.
		if len(output) == 0 {
			return 0, fmt.Errorf("failed to execute ping: %w", err)
		}
	}

	// Regex matches both Linux (rtt min/avg/max/mdev) and macOS (round-trip min/avg/max/stddev) formats.
	// It handles flexible whitespace, optional decimals, and captures the average value.
	re := regexp.MustCompile(`(?i)(?:rtt|round-trip)\s+min/avg/max/\w+\s*=\s*[\d.]+/([\d.]+)/[\d.]+/[\d.]+\s*ms`)
	matches := re.FindStringSubmatch(string(output))
	if len(matches) < 2 {
		return 0, errors.New("could not find or parse RTT statistics in ping output")
	}

	avg, err := strconv.ParseFloat(matches[1], 64)
	if err != nil {
		return 0, fmt.Errorf("failed to convert average latency to float: %w", err)
	}

	return avg, nil
}

