package main

import (
	"errors"
	"fmt"
	"os/exec"
	"regexp"
	"runtime"
	"strconv"
)

// MeasureLatency pings a specified host a given number of times and returns the average latency in milliseconds.
// It uses the system's native ping command via os/exec and parses the output for latency values.
func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, fmt.Errorf("count must be greater than 0")
	}

	// Determine platform-specific ping arguments
	var args []string
	switch runtime.GOOS {
	case "windows":
		args = []string{"-n", strconv.Itoa(count), host}
	default:
		args = []string{"-c", strconv.Itoa(count), host}
	}

	cmd := exec.Command("ping", args...)
	output, err := cmd.CombinedOutput()

	// ping may return a non-zero exit code on partial packet loss or unreachable hosts.
	// We proceed to parse the output unless the command itself failed to start or wasn't found.
	if err != nil {
		var exitErr *exec.ExitError
		if !errors.As(err, &exitErr) {
			return 0, fmt.Errorf("failed to execute ping command: %w", err)
		}
	}

	// Regex to capture latency values from ping output.
	// Matches patterns like "time=12.3 ms", "time<1 ms", "time=0.5ms" across Linux, macOS, and Windows.
	re := regexp.MustCompile(`time[=<]\s*([\d.]+)\s*ms`)
	matches := re.FindAllStringSubmatch(string(output), -1)

	if len(matches) == 0 {
		return 0, fmt.Errorf("no latency data found in ping output")
	}

	var totalLatency float64
	var validCount int
	for _, m := range matches {
		val, parseErr := strconv.ParseFloat(m[1], 64)
		if parseErr != nil {
			continue
		}
		totalLatency += val
		validCount++
	}

	if validCount == 0 {
		return 0, fmt.Errorf("failed to parse any valid latency values")
	}

	// Return average latency of successful replies
	return totalLatency / float64(validCount), nil
}

func main() {
	host := "8.8.8.8"
	count := 4

	fmt.Printf("Pinging %s %d times...\n", host, count)
	avg, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return
	}
	fmt.Printf("Average Latency: %.2f ms\n", avg)
}

