package main

import (
	"errors"
	"fmt"
	"os/exec"
	"regexp"
	"runtime"
	"strconv"
)

// MeasureLatency executes the system ping command against the specified host
// for the given number of attempts and returns the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	if host == "" {
		return 0, fmt.Errorf("host cannot be empty")
	}
	if count <= 0 {
		return 0, fmt.Errorf("count must be greater than 0")
	}

	var cmd *exec.Cmd
	switch runtime.GOOS {
	case "windows":
		cmd = exec.Command("ping", "-n", strconv.Itoa(count), host)
	default:
		cmd = exec.Command("ping", "-c", strconv.Itoa(count), host)
	}

	output, err := cmd.CombinedOutput()
	if err != nil {
		// ping may return a non-zero exit code on partial packet loss, but still prints statistics.
		// We only fail hard if the command could not be executed at all (e.g., not found, permission denied).
		var exitErr *exec.ExitError
		if !errors.As(err, &exitErr) {
			return 0, fmt.Errorf("failed to execute ping command: %w", err)
		}
	}

	avg, parseErr := parseAverageLatency(string(output))
	if parseErr != nil {
		if err != nil {
			return 0, fmt.Errorf("ping command failed: %w", err)
		}
		return 0, fmt.Errorf("failed to parse ping output: %w", parseErr)
	}

	return avg, nil
}

func parseAverageLatency(output string) (float64, error) {
	// Match Unix-like output (Linux, macOS, BSD)
	// Example: rtt min/avg/max/mdev = 0.025/0.030/0.035/0.003 ms
	reUnix := regexp.MustCompile(`(?i)(?:rtt|round-trip)\s+min/avg/max/(?:mdev|stddev)\s*=\s*[\d.]+/([\d.]+)/[\d.]+/[\d.]+\s*ms`)
	if matches := reUnix.FindStringSubmatch(output); len(matches) > 1 {
		return strconv.ParseFloat(matches[1], 64)
	}

	// Match Windows output
	// Example: Average = 10ms
	reWin := regexp.MustCompile(`(?i)Average\s*=\s*([\d.]+)\s*ms`)
	if matches := reWin.FindStringSubmatch(output); len(matches) > 1 {
		return strconv.ParseFloat(matches[1], 64)
	}

	return 0, fmt.Errorf("average latency not found in output")
}

func main() {
	host := "8.8.8.8"
	count := 4

	fmt.Printf("Pinging %s (%d attempts)...\n", host, count)
	avg, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return
	}
	fmt.Printf("Average latency: %.3f ms\n", avg)
}

