fix.generatedCode:
package main

import (
	"errors"
	"fmt"
	"os/exec"
	"regexp"
	"strconv"
)

// MeasureLatency pings the specified host the given number of times and returns the average latency in milliseconds.
// It uses the system 'ping' command via os/exec and parses the output to extract the average RTT.
func MeasureLatency(host string, count int) (float64, error) {
	if host == "" {
		return 0, errors.New("host cannot be empty")
	}
	if count <= 0 {
		return 0, errors.New("count must be positive")
	}

	// Execute ping directly without shell invocation for safety, efficiency, and proper argument escaping.
	cmd := exec.Command("ping", "-c", strconv.Itoa(count), host)
	output, err := cmd.CombinedOutput()
	if err != nil {
		return 0, fmt.Errorf("failed to execute ping: %w (output: %s)", err, string(output))
	}

	// Flexible regex to handle both Linux (rtt/min/avg/max/mdev) and macOS (round-trip/min/avg/max/stddev) formats.
	// Supports both integer and floating-point latency values, and accounts for varying whitespace.
	re := regexp.MustCompile(`(?i)(?:rtt|round-trip)\s+min/avg/max/(?:mdev|stddev)\s*=\s*\d+(?:\.\d+)?/(\d+(?:\.\d+)?)/\d+(?:\.\d+)?/\d+(?:\.\d+)?\s*ms`)
	matches := re.FindStringSubmatch(string(output))
	if len(matches) < 2 {
		return 0, errors.New("could not find or parse RTT statistics in ping output")
	}

	avg, err := strconv.ParseFloat(matches[1], 64)
	if err != nil {
		return 0, fmt.Errorf("failed to convert average latency to float: %w", err)
	}

	return avg, nil
}

