package main

import (
	"errors"
	"fmt"
	"os"
	"os/exec"
	"regexp"
	"runtime"
	"strconv"
)

// MeasureLatency pings a specified host a given number of times and returns
// the average latency in milliseconds. It uses os/exec to run the system ping command.
func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, fmt.Errorf("count must be greater than 0")
	}
	if host == "" {
		return 0, fmt.Errorf("host cannot be empty")
	}

	// Determine the correct flag for the number of pings based on OS
	flag := "-c"
	if runtime.GOOS == "windows" {
		flag = "-n"
	}

	cmd := exec.Command("ping", flag, strconv.Itoa(count), host)
	// Force C locale to ensure consistent, English-based output for reliable parsing
	cmd.Env = append(os.Environ(), "LC_ALL=C", "LANG=C")

	out, err := cmd.CombinedOutput()
	if err != nil {
		var exitErr *exec.ExitError
		if !errors.As(err, &exitErr) {
			return 0, fmt.Errorf("failed to execute ping command: %w", err)
		}
		// ping returns non-zero exit codes on packet loss or unreachable hosts,
		// but the output may still contain valid latency data to parse.
	}

	output := string(out)

	// 1. Try parsing Unix/macOS summary line:
	//    rtt min/avg/max/mdev = 0.025/0.030/0.035/0.005 ms
	//    round-trip min/avg/max/stddev = 1.2/3.4/5.6/0.1 ms
	unixRe := regexp.MustCompile(`(?:rtt|round-trip)\s+min/avg/max(?:/[a-z]+)?\s*=\s*[0-9.]+/([0-9.]+)`)
	if matches := unixRe.FindStringSubmatch(output); len(matches) > 1 {
		return strconv.ParseFloat(matches[1], 64)
	}

	// 2. Try parsing Windows summary line:
	//    Average = 14ms
	winRe := regexp.MustCompile(`Average\s*=\s*([0-9.]+)ms`)
	if matches := winRe.FindStringSubmatch(output); len(matches) > 1 {
		return strconv.ParseFloat(matches[1], 64)
	}

	// 3. Fallback: Calculate average manually from individual reply times
	//    Matches patterns like: time=12.34 ms or time=0.123ms
	timeRe := regexp.MustCompile(`time=([0-9.]+)\s*ms`)
	timeMatches := timeRe.FindAllStringSubmatch(output, -1)
	if len(timeMatches) == 0 {
		return 0, fmt.Errorf("no latency data found in ping output")
	}

	var total float64
	var validCount int
	for _, m := range timeMatches {
		val, err := strconv.ParseFloat(m[1], 64)
		if err != nil {
			continue
		}
		total += val
		validCount++
	}

	if validCount == 0 {
		return 0, fmt.Errorf("failed to parse latency values from ping output")
	}

	return total / float64(validCount), nil
}

func main() {
	host := "8.8.8.8"
	count := 4

	avg, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error measuring latency: %v\n", err)
		os.Exit(1)
	}

	fmt.Printf("Average latency to %s over %d pings: %.2f ms\n", host, count, avg)
}

