package main

import (
	"fmt"
	"os"
	"os/exec"
	"regexp"
	"runtime"
	"strconv"
)

// MeasureLatency pings the specified host a given number of times and returns the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, fmt.Errorf("count must be greater than 0")
	}

	var cmd *exec.Cmd
	switch runtime.GOOS {
	case "windows":
		cmd = exec.Command("ping", "-n", strconv.Itoa(count), host)
	default:
		cmd = exec.Command("ping", "-c", strconv.Itoa(count), host)
	}

	// Force C/POSIX locale to ensure consistent, parseable numeric formats across different system languages
	cmd.Env = append(os.Environ(), "LC_ALL=C", "LANG=C")

	output, err := cmd.CombinedOutput()
	if err != nil {
		// ping may return a non-zero exit code on packet loss, timeouts, or unreachable hosts.
		// We continue to parse the output anyway, as partial statistics might still be present.
	}

	return parsePingOutput(string(output))
}

// parsePingOutput extracts the average latency from the raw ping command output.
func parsePingOutput(output string) (float64, error) {
	// Regex for Linux/macOS summary lines:
	// rtt min/avg/max/mdev = 10.123/11.456/12.789/0.987 ms
	// round-trip min/avg/max/stddev = 10.123/11.456/12.789/0.987 ms
	reUnix := regexp.MustCompile(`(?i)(?:rtt|round-trip)\s+min/avg/max/(?:mdev|stddev)\s*=\s*[\d.]+/([\d.]+)/[\d.]+/[\d.]+\s*ms`)
	if matches := reUnix.FindStringSubmatch(output); len(matches) > 1 {
		return strconv.ParseFloat(matches[1], 64)
	}

	// Regex for Windows summary line:
	// Average = 11ms
	reWin := regexp.MustCompile(`(?i)Average\s*=\s*([\d.]+)\s*ms`)
	if matches := reWin.FindStringSubmatch(output); len(matches) > 1 {
		return strconv.ParseFloat(matches[1], 64)
	}

	return 0, fmt.Errorf("failed to parse average latency from ping output")
}

func main() {
	host := "8.8.8.8"
	count := 4

	avg, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error measuring latency: %v\n", err)
		os.Exit(1)
	}

	fmt.Printf("Average latency to %s over %d attempts: %.2f ms\n", host, count, avg)
}

