package main

import (
	"fmt"
	"os/exec"
	"regexp"
	"runtime"
	"strconv"
)

// latencyRegex extracts latency values from ping output across major OS families.
// Matches formats like: time=12.34 ms, time=0.030 ms, time<1ms
var latencyRegex = regexp.MustCompile(`time[=<](\d+\.?\d*)\s*ms`)

// MeasureLatency pings a specified host a user-defined number of times and returns
// the average latency in milliseconds based on successful replies.
func MeasureLatency(host string, count int) (float64, error) {
	if host == "" {
		return 0, fmt.Errorf("host cannot be empty")
	}
	if count <= 0 {
		return 0, fmt.Errorf("count must be greater than 0")
	}

	// Build OS-specific ping command
	var cmd *exec.Cmd
	switch runtime.GOOS {
	case "windows":
		cmd = exec.Command("ping", "-n", strconv.Itoa(count), host)
	default:
		cmd = exec.Command("ping", "-c", strconv.Itoa(count), host)
	}

	// Execute command and capture combined stdout/stderr
	out, err := cmd.CombinedOutput()
	outputStr := string(out)

	// Extract all successful latency measurements
	matches := latencyRegex.FindAllStringSubmatch(outputStr, -1)
	if len(matches) == 0 {
		if err != nil {
			return 0, fmt.Errorf("ping command failed: %v, output: %s", err, outputStr)
		}
		return 0, fmt.Errorf("no latency data found in ping output")
	}

	// Calculate average latency from successful replies
	var totalLatency float64
	for _, m := range matches {
		val, parseErr := strconv.ParseFloat(m[1], 64)
		if parseErr != nil {
			continue
		}
		totalLatency += val
	}

	avgLatency := totalLatency / float64(len(matches))
	return avgLatency, nil
}

func main() {
	host := "8.8.8.8"
	count := 4

	avg, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error measuring latency: %v\n", err)
		return
	}

	fmt.Printf("Average latency to %s over %d attempts: %.2f ms\n", host, count, avg)
}

