import (
	"fmt"
	"os/exec"
	"regexp"
	"runtime"
	"strconv"
)

// MeasureLatency pings the specified host a given number of times and returns the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, fmt.Errorf("count must be greater than 0")
	}

	var args []string
	if runtime.GOOS == "windows" {
		args = []string{"-n", strconv.Itoa(count), host}
	} else {
		args = []string{"-c", strconv.Itoa(count), host}
	}

	cmd := exec.Command("ping", args...)
	out, _ := cmd.CombinedOutput()
	outputStr := string(out)

	// ping may return a non-zero exit code on partial packet loss or timeout,
	// but we can still parse the output if latency data is present.
	// We proceed to parse regardless of the exec error.

	// Try to extract individual ping times first (e.g., time=14.2 ms)
	timeRe := regexp.MustCompile(`(?i)time\s*=\s*([0-9.]+)\s*ms`)
	matches := timeRe.FindAllStringSubmatch(outputStr, -1)

	if len(matches) > 0 {
		var total float64
		var validCount int
		for _, m := range matches {
			val, parseErr := strconv.ParseFloat(m[1], 64)
			if parseErr == nil {
				total += val
				validCount++
			}
		}
		if validCount > 0 {
			return total / float64(validCount), nil
		}
	}

	// Fallback: parse summary average line (e.g., rtt min/avg/max/mdev = ... or Average = 14ms)
	avgRe := regexp.MustCompile(`(?i)(?:avg|average)[^=]*=\s*([0-9.]+)\s*ms`)
	avgMatches := avgRe.FindStringSubmatch(outputStr)
	if len(avgMatches) > 1 {
		avg, parseErr := strconv.ParseFloat(avgMatches[1], 64)
		if parseErr == nil {
			return avg, nil
		}
	}

	return 0, fmt.Errorf("failed to parse latency from ping output: %s", outputStr)
}

func main() {
	host := "8.8.8.8"
