package main

import (
	"fmt"
	"os/exec"
	"regexp"
	"runtime"
	"strconv"
	"strings"
)

// MeasureLatency pings the specified host a given number of times and returns
// the average latency in milliseconds. It uses the system's ping command via os/exec.
func MeasureLatency(host string, count int) (float64, error) {
	if host == "" {
		return 0, fmt.Errorf("host cannot be empty")
	}
	if count <= 0 {
		return 0, fmt.Errorf("count must be greater than 0")
	}

	// Determine the correct flag for the number of pings based on OS
	flag := "-c"
	if runtime.GOOS == "windows" {
		flag = "-n"
	}

	cmd := exec.Command("ping", flag, strconv.Itoa(count), host)
	out, err := cmd.CombinedOutput()

	// Regex captures latency values from standard ping outputs:
	// Linux/macOS: time=12.345 ms or time<0.1 ms
	// Windows:     time=14ms or time<1ms
	re := regexp.MustCompile(`time[=<]([\d.]+)\s*ms`)
	matches := re.FindAllStringSubmatch(string(out), -1)

	if len(matches) == 0 {
		if err != nil {
			return 0, fmt.Errorf("ping command failed: %v\nOutput: %s", err, strings.TrimSpace(string(out)))
		}
		return 0, fmt.Errorf("no valid ping replies received")
	}

	var totalLatency float64
	var validCount int
	for _, m := range matches {
		latency, parseErr := strconv.ParseFloat(m[1], 64)
		if parseErr == nil {
			totalLatency += latency
			validCount++
		}
	}

	if validCount == 0 {
		return 0, fmt.Errorf("failed to parse latency values from ping output")
	}

	// Calculate and return the average latency
	return totalLatency / float64(validCount), nil
}

func main() {
	host := "8.8.8.8"
	count := 4

	avg, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error measuring latency: %v\n", err)
		return
	}

	fmt.Printf("Average latency to %s over %d pings: %.2f ms\n", host, count, avg)
}

