package main

import (
	"fmt"
	"os/exec"
	"regexp"
	"runtime"
	"strconv"
)

// latencyRegex extracts the latency value from ping output across major OS families.
// Matches patterns like: time=14.2 ms, time=14ms, time<1ms
var latencyRegex = regexp.MustCompile(`(?i)time[=<]([0-9.]+)\s*ms`)

// MeasureLatency pings a specified host a user-defined number of times and returns
// the average latency in milliseconds. It uses os/exec to run the system ping command.
func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, fmt.Errorf("count must be greater than 0")
	}

	var cmd *exec.Cmd
	switch runtime.GOOS {
	case "windows":
		cmd = exec.Command("ping", "-n", strconv.Itoa(count), host)
	default: // linux, darwin, freebsd, etc.
		cmd = exec.Command("ping", "-c", strconv.Itoa(count), host)
	}

	output, err := cmd.CombinedOutput()
	if err != nil && len(output) == 0 {
		return 0, fmt.Errorf("failed to execute ping command: %w", err)
	}

	matches := latencyRegex.FindAllStringSubmatch(string(output), -1)
	if len(matches) == 0 {
		return 0, fmt.Errorf("no latency data found in ping output")
	}

	var totalLatency float64
	var validCount int
	for _, match := range matches {
		latency, parseErr := strconv.ParseFloat(match[1], 64)
		if parseErr != nil {
			continue
		}
		totalLatency += latency
		validCount++
	}

	if validCount == 0 {
		return 0, fmt.Errorf("failed to parse any valid latency values from output")
	}

	return totalLatency / float64(validCount), nil
}

func main() {
	host := "8.8.8.8"
	count := 4

	avg, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error measuring latency: %v\n", err)
		return
	}
	fmt.Printf("Average latency to %s over %d attempts: %.3f ms\n", host, count, avg)
}

