// MeasureLatency pings the specified host a given number of times and returns
// the average latency in milliseconds. It uses the system's ping command via os/exec.
func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, fmt.Errorf("count must be greater than 0")
	}

	// Determine the correct flag for the number of pings based on the OS
	var countFlag string
	switch runtime.GOOS {
	case "windows":
		countFlag = "-n"
	default:
		countFlag = "-c"
	}

	cmd := exec.Command("ping", countFlag, strconv.Itoa(count), host)
	out, err := cmd.CombinedOutput()

	// ping may return a non-zero exit code on packet loss or timeouts.
	// We only fail immediately if the command could not be executed at all (e.g., ping not found).
	if err != nil {
		if _, ok := err.(*exec.ExitError); !ok {
			return 0, fmt.Errorf("failed to execute ping command: %w", err)
		}
	}

	output := string(out)
	// Regex matches patterns like "time=14.3 ms", "time<1ms", "time=0.045 ms"
	// It is case-insensitive and handles optional whitespace around the value.
	re := regexp.MustCompile(`(?i)time[=<]\s*([0-9.]+)\s*ms`)
	matches := re.FindAllStringSubmatch(output, -1)

	if len(matches) == 0 {
		return 0, fmt.Errorf("no latency data found in ping output for host %q", host)
	}

	var totalLatency float64
	var validCount int
	for _, m := range matches {
		val, parseErr := strconv.ParseFloat(m[1], 64)
		if parseErr != nil {
			continue
		}
		totalLatency += val
		validCount++
	}

	if validCount == 0 {
		return 0, fmt.Errorf("failed to parse any valid latency values from ping output")
	}

	return totalLatency / float64(validCount), nil
}

func main() {
	host := "8.8.8.8"
	count := 4

	fmt.Printf("Pinging %s %d times...\n", host, count)
	avg, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error measuring latency: %v\n", err)
		return
	}
	fmt.Printf("Average latency: %.2f ms\n", avg)
}

