	"strconv"
)

// MeasureLatency pings a specified host a given number of times and returns
// the average latency in milliseconds. It uses os/exec to run the system ping command.
func MeasureLatency(host string, count int) (float64, error) {
	if host == "" {
		return 0, fmt.Errorf("host cannot be empty")
	}
	if count <= 0 {
		return 0, fmt.Errorf("count must be greater than 0")
	}

	var cmd *exec.Cmd
	switch runtime.GOOS {
	case "windows":
		cmd = exec.Command("ping", "-n", strconv.Itoa(count), host)
	default: // linux, darwin, freebsd, etc.
		cmd = exec.Command("ping", "-c", strconv.Itoa(count), host)
		// Force C locale to ensure consistent, parseable output across different system languages
		cmd.Env = append(os.Environ(), "LC_ALL=C")
	}

	output, err := cmd.CombinedOutput()
	// ping may return a non-zero exit code on partial packet loss, but output is still valid.
	// Only fail immediately if there's no output at all.
	if err != nil && len(output) == 0 {
		return 0, fmt.Errorf("failed to execute ping command: %w", err)
	}

