			if parseErr == nil {
				totalLatency += val
				validPings++
			}
		}
	}

	if validPings == 0 {
		return 0, fmt.Errorf("failed to parse any valid latency values from ping output")
	}

	return totalLatency / float64(validPings), nil
}

func main() {
	host := "8.8.8.8"
	count := 4

	fmt.Printf("Pinging %s %d times...\n", host, count)
	avgLatency, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error measuring latency: %v\n", err)
		os.Exit(1)
	}

	fmt.Printf("Average latency: %.2f ms\n", avgLatency)
}

