// MeasureLatency pings a specified host a given number of times and returns the average latency in milliseconds.
// It uses the system's native ping command via os/exec and parses the output cross-platform.
func MeasureLatency(host string, count int) (float64, error) {
	if strings.TrimSpace(host) == "" {
		return 0, fmt.Errorf("host cannot be empty")
	}
	if count <= 0 {
		return 0, fmt.Errorf("count must be greater than 0")
	}

	var cmd *exec.Cmd
	switch runtime.GOOS {
	case "windows":
		cmd = exec.Command("ping", "-n", strconv.Itoa(count), host)
	default:
		cmd = exec.Command("ping", "-c", strconv.Itoa(count), host)
	}

	out, err := cmd.CombinedOutput()
	outputStr := string(out)

	// ping may return a non-zero exit code on packet loss or unreachable hosts.
	// We only fail immediately if the command produced no output at all.
	if err != nil && len(outputStr) == 0 {
		return 0, fmt.Errorf("failed to execute ping command: %w", err)
	}

	// Regex patterns to extract average latency from different OS ping outputs.
	// Linux:      rtt min/avg/max/mdev = 10.123/11.456/12.789/0.987 ms
	// macOS:      round-trip min/avg/max/stddev = 10.123/11.456/12.789/0.987 ms
	unixRegex := regexp.MustCompile(`(?i)(?:rtt|round-trip)\s+min/avg/max/\w+\s*=\s*[\d.,]+/([\d.,]+)`)
	// Windows:    Average = 11ms
	winRegex := regexp.MustCompile(`(?i)Average\s*=\s*([\d.,]+)`)

	var avgStr string
	if matches := unixRegex.FindStringSubmatch(outputStr); len(matches) > 1 {
		avgStr = matches[1]
	} else if matches := winRegex.FindStringSubmatch(outputStr); len(matches) > 1 {
		avgStr = matches[1]
	} else {
		return 0, fmt.Errorf("failed to parse average latency from ping output:\n%s", outputStr)
	}

	// Handle locales that use commas for decimal separators
	avgStr = strings.ReplaceAll(avgStr, ",", ".")

	avgLatency, err := strconv.ParseFloat(strings.TrimSpace(avgStr), 64)
	if err != nil {
		return 0, fmt.Errorf("failed to convert latency value to float: %w", err)
	}

	return avgLatency, nil
}

func main() {
	host := "8.8.8.8"
	count := 4

	fmt.Printf("Measuring latency for %s (%d attempts)...\n", host, count)
	avg, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return
	}
	fmt.Printf("Average Latency: %.2f ms\n", avg)
}

