package main

import (
	"fmt"
	"os/exec"
	"regexp"
	"runtime"
	"strconv"
)

// MeasureLatency pings a specified host a given number of times and returns
// the average latency in milliseconds. It uses os/exec to run the system ping command.
// Note: The average is calculated over successful ping replies. Packet loss will
// reduce the denominator accordingly, which matches standard network tool behavior.
func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, fmt.Errorf("count must be greater than 0")
	}

	// Determine the correct flag for the number of pings based on OS
	pingCountFlag := "-c"
	if runtime.GOOS == "windows" {
		pingCountFlag = "-n"
	}

	cmd := exec.Command("ping", pingCountFlag, strconv.Itoa(count), host)
	out, err := cmd.CombinedOutput()
	if err != nil {
		// ping returns a non-zero exit code on packet loss or unreachable hosts.
		// If there's no output at all, the command fundamentally failed.
		if len(out) == 0 {
			return 0, fmt.Errorf("ping command failed: %w", err)
		}
		// If we have output, proceed to parse partial results (e.g., some packets succeeded)
	}

	// Regex matches latency values in standard ping output formats:
	// Unix/Linux/macOS: time=14.2 ms
	// Windows: time<1ms or time=10ms
	re := regexp.MustCompile(`time[=<]([0-9.]+)\s*ms`)
	matches := re.FindAllStringSubmatch(string(out), -1)

	if len(matches) == 0 {
		return 0, fmt.Errorf("no latency data found in ping output for host %s", host)
	}

	var totalLatency float64
	validPings := 0
	for _, match := range matches {
		latency, parseErr := strconv.ParseFloat(match[1], 64)
		if parseErr != nil {
			continue
		}
		totalLatency += latency
		validPings++
	}

	if validPings == 0 {
		return 0, fmt.Errorf("failed to parse any valid latency values from ping output")
	}

	avgLatency := totalLatency / float64(validPings)
	return avgLatency, nil
}

func main() {
	host := "8.8.8.8"
	count := 4

	fmt.Printf("Pinging %s %d times...\n", host, count)
	avg, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error measuring latency: %v\n", err)
		return
	}

	fmt.Printf("Average latency: %.3f ms\n", avg)
}

