package main

import (
	"fmt"
	"os/exec"
	"regexp"
	"runtime"
	"strconv"
)

var (
	// Regex for Linux/macOS ping summary: rtt min/avg/max/mdev = 10.123/12.456/15.789/1.234 ms
	unixPingAvgRegex = regexp.MustCompile(`min/avg/max.*=\s*[\d.]+/([\d.]+)/`)
	// Regex for Windows ping summary: Average = 12ms
	windowsPingAvgRegex = regexp.MustCompile(`(?i)Average\s*=\s*([\d.]+)\s*ms`)
)

// MeasureLatency pings a specified host a given number of times and returns the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	if host == "" {
		return 0, fmt.Errorf("host cannot be empty")
	}
	if count <= 0 {
		return 0, fmt.Errorf("count must be greater than zero")
	}

	// Configure ping command arguments based on OS
	var args []string
	switch runtime.GOOS {
	case "windows":
		args = []string{"-n", strconv.Itoa(count), host}
	default: // linux, darwin, freebsd, etc.
		args = []string{"-c", strconv.Itoa(count), host}
	}

	cmd := exec.Command("ping", args...)
	out, err := cmd.CombinedOutput()
	outputStr := string(out)

	// Parse the output to extract average latency
	avg, parseErr := parsePingOutput(outputStr, runtime.GOOS)
	if parseErr != nil {
		// If parsing fails, return the underlying exec error if present, otherwise the parse error
		if err != nil {
			return 0, fmt.Errorf("ping command failed: %w\nOutput: %s", err, outputStr)
		}
		return 0, fmt.Errorf("failed to parse ping output: %w", parseErr)
	}

	return avg, nil
}

// parsePingOutput extracts the average latency from the raw ping command output.
func parsePingOutput(output, goos string) (float64, error) {
	var re *regexp.Regexp
	if goos == "windows" {
		re = windowsPingAvgRegex
	} else {
		re = unixPingAvgRegex
	}

	matches := re.FindStringSubmatch(output)
	if len(matches) < 2 {
		return 0, fmt.Errorf("average latency not found in output")
	}

	avg, err := strconv.ParseFloat(matches[1], 64)
	if err != nil {
		return 0, fmt.Errorf("invalid latency format: %w", err)
	}
	return avg, nil
}

func main() {
	host := "8.8.8.8"
	count := 4
	fmt.Printf("Measuring latency to %s (%d attempts)...\n", host, count)

	avg, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return
	}
	fmt.Printf("Average Latency: %.2f ms\n", avg)
}

