package main

import (
	"fmt"
	"os/exec"
	"regexp"
	"runtime"
	"strconv"
	"strings"
)

// MeasureLatency pings a specified host a given number of times and returns
// the average latency in milliseconds. It uses os/exec to run the system ping command.
func MeasureLatency(host string, count int) (float64, error) {
	if host == "" {
		return 0, fmt.Errorf("host cannot be empty")
	}
	if count <= 0 {
		return 0, fmt.Errorf("count must be greater than 0")
	}

	// Determine the correct flag for the number of pings based on OS
	flag := "-c"
	if runtime.GOOS == "windows" {
		flag = "-n"
	}

	cmd := exec.Command("ping", flag, strconv.Itoa(count), host)
	out, err := cmd.Output()
	if err != nil {
		return 0, fmt.Errorf("ping command failed: %w", err)
	}

	outputStr := string(out)
	var avgStr string
	var found bool

	// Parse Unix-like output (Linux, macOS, BSD)
	// Typical format: rtt min/avg/max/mdev = 1.234/5.678/9.012/0.345 ms
	// or: round-trip min/avg/max/stddev = 1.234/5.678/9.012/0.345 ms
	reUnix := regexp.MustCompile(`min/avg/max[^=]*=\s*[0-9.,]+/([0-9.,]+)/`)
	if matches := reUnix.FindStringSubmatch(outputStr); len(matches) > 1 {
		avgStr = matches[1]
		found = true
	}

	// Parse Windows output if Unix pattern didn't match
	// Typical format: Average = 10ms
	if !found {
		reWin := regexp.MustCompile(`(?i)Average\s*=\s*([0-9.,]+)`)
		if matches := reWin.FindStringSubmatch(outputStr); len(matches) > 1 {
			avgStr = matches[1]
			found = true
		}
	}

	if !found {
		return 0, fmt.Errorf("could not parse average latency from ping output")
	}

	// Handle locales that use commas as decimal separators
	avgStr = strings.ReplaceAll(avgStr, ",", ".")
	avg, err := strconv.ParseFloat(avgStr, 64)
	if err != nil {
		return 0, fmt.Errorf("failed to parse latency value: %w", err)
	}

	return avg, nil
}

func main() {
	host := "8.8.8.8"
	count := 4

	avg, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error measuring latency: %v\n", err)
		return
	}

	fmt.Printf("Average latency to %s over %d pings: %.2f ms\n", host, count, avg)
}

