package main

import (
	"fmt"
	"os/exec"
	"regexp"
	"runtime"
	"strconv"
)

// MeasureLatency pings a specified host a given number of times and returns the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, fmt.Errorf("count must be greater than 0")
	}

	// Determine ping command arguments based on the operating system
	var args []string
	if runtime.GOOS == "windows" {
		args = []string{"-n", strconv.Itoa(count), host}
	} else {
		args = []string{"-c", strconv.Itoa(count), host}
	}

	cmd := exec.Command("ping", args...)
	out, err := cmd.CombinedOutput()

	// ping may return a non-zero exit code on packet loss, but stdout/stderr still contains valid data.
	// We only treat it as a hard failure if there's no output at all.
	if err != nil && len(out) == 0 {
		return 0, fmt.Errorf("failed to execute ping command: %w", err)
	}

	// Regex to extract latency values from ping output.
	// Matches patterns like "time=14.2 ms", "time = 14ms", etc. (case-insensitive)
	re := regexp.MustCompile(`(?i)time\s*=\s*([0-9.]+)\s*ms`)
	matches := re.FindAllStringSubmatch(string(out), -1)

	if len(matches) == 0 {
		return 0, fmt.Errorf("no latency data found in ping output for host %s", host)
	}

	var totalLatency float64
	var successCount int

	for _, match := range matches {
		if len(match) > 1 {
			latency, parseErr := strconv.ParseFloat(match[1], 64)
			if parseErr == nil {
				totalLatency += latency
				successCount++
			}
		}
	}

	if successCount == 0 {
		return 0, fmt.Errorf("failed to parse any valid latency values from ping output")
	}

	return totalLatency / float64(successCount), nil
}

func main() {
	host := "8.8.8.8"
	count := 4

	fmt.Printf("Pinging %s %d times...\n", host, count)
	avgLatency, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error measuring latency: %v\n", err)
		return
	}

	fmt.Printf("Average latency: %.2f ms\n", avgLatency)
}

