package main

import (
	"fmt"
	"os/exec"
	"regexp"
	"runtime"
	"strconv"
)

// MeasureLatency pings the specified host a given number of times and returns
// the average latency in milliseconds. It uses os/exec to run the system ping command.
func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, fmt.Errorf("count must be greater than 0")
	}

	// Prepare platform-specific arguments for the ping command
	var args []string
	if runtime.GOOS == "windows" {
		args = []string{"-n", strconv.Itoa(count), host}
	} else {
		args = []string{"-c", strconv.Itoa(count), host}
	}

	cmd := exec.Command("ping", args...)
	out, err := cmd.CombinedOutput()

	// ping may return a non-zero exit code on partial packet loss,
	// so we proceed to parse the output regardless of err.
	outputStr := string(out)

	// Regex matches individual ping response times across Linux, macOS, and Windows.
	// Examples: time=14.2 ms, time<1ms, time=14.234 ms
	re := regexp.MustCompile(`time[=<]([\d.]+)\s*ms`)
	matches := re.FindAllStringSubmatch(outputStr, -1)

	if len(matches) == 0 {
		if err != nil {
			return 0, fmt.Errorf("ping command failed: %v\noutput: %s", err, outputStr)
		}
		return 0, fmt.Errorf("no ping responses received or unable to parse output")
	}

	var totalLatency float64
	var validPings int
	for _, m := range matches {
		latency, parseErr := strconv.ParseFloat(m[1], 64)
		if parseErr == nil {
			totalLatency += latency
			validPings++
		}
	}

	if validPings == 0 {
		return 0, fmt.Errorf("failed to extract valid latency values from ping output")
	}

	averageLatency := totalLatency / float64(validPings)
	return averageLatency, nil
}

func main() {
	host := "8.8.8.8"
	count := 4

	fmt.Printf("Pinging %s (%d attempts)...\n", host, count)
	avg, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error measuring latency: %v\n", err)
		return
	}

	fmt.Printf("Average latency: %.3f ms\n", avg)
}

