		// but still prints statistics. We proceed to parse if output exists.
		if len(out) == 0 {
			return 0, fmt.Errorf("ping command failed: %w", err)
		}
	}

	outputStr := string(out)

	// Regex for Unix-like systems (Linux, macOS, BSD)
	// Matches lines like: rtt min/avg/max/mdev = 1.023/2.456/5.123/1.000 ms
	// or: round-trip min/avg/max/stddev = 1.023/2.456/5.123/1.000 ms
	reUnix := regexp.MustCompile(`(?:rtt|round-trip)\s+min/avg/max/(?:mdev|stddev)\s*=\s*[\d.]+/([\d.]+)/[\d.]+/[\d.]+\s*ms`)

	// Regex for Windows
	// Matches lines like: Average = 14ms
	reWin := regexp.MustCompile(`Average\s*=\s*([\d.]+)ms`)

	var avgStr string
	if matches := reUnix.FindStringSubmatch(outputStr); len(matches) > 1 {
		avgStr = matches[1]
	} else if matches := reWin.FindStringSubmatch(outputStr); len(matches) > 1 {
		avgStr = matches[1]
	} else {
		return 0, fmt.Errorf("failed to parse average latency from ping output:\n%s", strings.TrimSpace(outputStr))
	}

	avg, err := strconv.ParseFloat(avgStr, 64)
	if err != nil {
		return 0, fmt.Errorf("failed to convert latency value to float: %w", err)
	}

	return avg, nil
}

func main() {
	host := "8.8.8.8"
	count := 4

	avg, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error measuring latency: %v\n", err)
		os.Exit(1)
	}

	fmt.Printf("Average latency to %s (%d pings): %.3f ms\n", host, count, avg)
}

